#!/usr/bin/env python3
"""Reconstructed WebShop HTTP adapter; CPU service, one process per port.

This is NOT the missing historical service. It fixes a new, explicit environment
revision for both experimental arms. Use the upstream 1000-product dataset and
all 6910 synthetic goals; no miniature fixture is available in the runtime CLI.
"""
from __future__ import annotations

import argparse
from datetime import datetime, timezone
import hashlib
from importlib import metadata
import inspect
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import itertools
import json
import math
from pathlib import Path
import platform
import random
import subprocess
import sys
import threading
import time
import uuid

UPSTREAM_COMMIT = "64fa2a5c15c7daa698b9ac93f5bb5437b634c9bd"
SERVICE_REVISION = "reconstructed-webshop-http-v3-idempotent"
TRANSPORT_PROTOCOL = 3


def sha256_file(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def dataset_source_manifest(upstream, files):
    path = upstream.parent / "data-source-manifest.json"
    if not path.exists():
        return {"present": False, "official_original_byte_equivalence": "UNVERIFIED"}
    if path.is_symlink():
        raise ValueError("Refusing linked dataset source manifest")
    manifest = json.loads(path.read_text())
    records = manifest.get("files", {})
    for item in files:
        record = records.get(item.name, {})
        if item.is_symlink() or record.get("size") != item.stat().st_size or record.get("sha256") != sha256_file(item):
            raise ValueError(f"Dataset source manifest mismatch: {item.name}")
        if "git_blob_sha1" in record:
            raw = item.read_bytes()
            oid = hashlib.sha1(b"blob " + str(len(raw)).encode() + b"\0" + raw).hexdigest()
            if oid != record["git_blob_sha1"]:
                raise ValueError(f"Dataset source Git blob mismatch: {item.name}")
    return {"present": True, "manifest_sha256": sha256_file(path), "content": manifest}


def reindex_goals(goals, *, upstream_seed=233, seed=0):
    """Undo the pinned upstream shuffle, then apply our declared seed-0 order."""
    permutation = list(range(len(goals)))
    random.Random(upstream_seed).shuffle(permutation)
    canonical = [None] * len(goals)
    for shuffled_index, original_index in enumerate(permutation):
        canonical[original_index] = goals[shuffled_index]
    random.Random(seed).shuffle(canonical)
    return canonical


def option_fixed_reward(original_reward):
    """Keep upstream scoring; supply goal option values instead of (key, value).

    The pinned get_reward passes goal['goal_options'].items() to a function
    expecting strings. A shallow copy with values as a list takes its existing
    non-dict branch and leaves normalization, matching, weights and diagnostics
    unchanged. Never mutate the goal shared by concurrent episodes.
    """
    def reward(purchased_product, goal, price, options, **kwargs):
        if isinstance(goal["goal_options"], dict):
            goal = {**goal, "goal_options": list(goal["goal_options"].values())}
        return original_reward(purchased_product, goal, price, options, **kwargs)
    return reward


class ServiceError(Exception):
    def __init__(self, status, message):
        super().__init__(message)
        self.status = status


class OfficialBackend:
    def __init__(self, upstream: Path, *, option_fix=True):
        upstream = upstream.resolve()
        source_manifest = upstream.parent / "source-manifest.json"
        if source_manifest.exists():
            from webshop_source import verify_source
            source_provenance = verify_source(upstream, source_manifest)
            commit = UPSTREAM_COMMIT
        else:
            commit = subprocess.check_output(["git", "-C", str(upstream), "rev-parse", "HEAD"], text=True).strip()
            if commit != UPSTREAM_COMMIT:
                raise ValueError(f"WebShop revision mismatch: expected {UPSTREAM_COMMIT}, got {commit}")
            if subprocess.run(["git", "-C", str(upstream), "diff", "--quiet", "HEAD", "--", "web_agent_site", "search_engine"], check=False).returncode:
                raise ValueError("upstream environment source has local changes; freeze a new revision before using it")
            source_provenance = {"source_kind": "git_checkout", "git_checkout_verified": True}
        files = [upstream / "data" / name for name in (
            "items_shuffle_1000.json", "items_ins_v2_1000.json", "items_human_ins.json"
        )]
        for path in files:
            if not path.is_file():
                raise ValueError(f"required WebShop data missing: {path}")
        data_provenance = dataset_source_manifest(upstream, files)
        if not (upstream / "search_engine/indexes_1k").is_dir():
            raise ValueError("Lucene indexes_1k missing; run the cloud bootstrap first")
        sys.path.insert(0, str(upstream))
        from web_agent_site.engine import goal as goal_module
        from web_agent_site.envs import web_agent_text_env as text_env
        self.option_fix = bool(option_fix)
        # SimServer imports get_reward by value, so patch its module binding.
        text_env.get_reward = (option_fixed_reward(goal_module.get_reward)
                               if self.option_fix else goal_module.get_reward)

        # These seeds are a reconstruction contract, not recovered historical facts.
        random.seed(0)
        self.server = text_env.SimServer("http://127.0.0.1:3000", str(files[0]), num_products=1000,
                                human_goals=False, show_attrs=False)
        self.server.goals = reindex_goals(self.server.goals)
        self.server.weights = [goal["weight"] for goal in self.server.goals]
        self.server.cum_weights = [0] + list(itertools.accumulate(self.server.weights))
        self.num_goals = len(self.server.goals)
        if self.num_goals != 6910 or len(self.server.all_products) != 1000:
            raise ValueError(f"expected 1000 products and 6910 goals; got {len(self.server.all_products)} and {self.num_goals}")
        self.env_class = text_env.WebAgentTextEnv
        index_root = upstream / "search_engine/indexes_1k"
        self.provenance = {
            "reconstructed": True, "service_revision": SERVICE_REVISION,
            "service_sha256": sha256_file(Path(__file__)), "upstream_commit": commit,
            "upstream_source": source_provenance,
            "upstream_repository": "https://github.com/princeton-nlp/WebShop",
            "product_goal_generation_seed": 0, "goal_shuffle_seed": 0,
            "goal_order_method": "invert pinned upstream seed-233 permutation; shuffle canonical order with seed 0",
            "option_fix": self.option_fix, "human_goals": False, "num_products": 1000,
            "option_fix_method": "shallow-copy dict goal_options to list(values()) before unchanged upstream get_reward",
            "option_fix_implementation_sha256": hashlib.sha256(inspect.getsource(option_fixed_reward).encode()).hexdigest(),
            "upstream_reward_source_sha256": sha256_file(upstream / "web_agent_site/engine/goal.py"),
            "python": platform.python_version(),
            "runtime_packages": {name: metadata.version(name) for name in
                                 ("spacy", "en-core-web-sm", "thefuzz", "pyserini", "gym", "Flask", "numpy")},
            "dataset_sha256": {path.name: sha256_file(path) for path in files},
            "dataset_source_manifest": data_provenance,
            "index_sha256": {str(path.relative_to(index_root)): sha256_file(path)
                             for path in sorted(index_root.rglob("*")) if path.is_file() and path.name != "write.lock"},
            "goals_sha256": hashlib.sha256(json.dumps(self.server.goals, sort_keys=True, ensure_ascii=False, default=str).encode()).hexdigest(),
            "product_prices_sha256": hashlib.sha256(json.dumps(self.server.product_prices, sort_keys=True).encode()).hexdigest(),
            "limitation": "Historical HTTP service and its exact patches were unavailable. New arms share this reconstruction; historical scores are reference only.",
        }

    def create(self, goal_idx, sid):
        previous = set(self.server.user_sessions)
        try:
            env = self.env_class(server=self.server, observation_mode="text", session_prefix=f"{sid}_",
                                 num_products=1000, human_goals=False)
            # Upstream __init__ creates a random session; only the explicit goal is retained.
            self.server.user_sessions.pop(env.session, None)
            observation, _ = env.reset(session=goal_idx)
            return env, {"observation": observation, "instruction": env.get_instruction_text(),
                         "actions": env.get_available_actions()}
        except Exception:
            for key in set(self.server.user_sessions) - previous:
                self.server.user_sessions.pop(key, None)
            raise

    def step(self, env, action):
        observation, reward, done, _ = env.step(action)
        return {"observation": observation, "reward": float(reward), "done": bool(done),
                "actions": env.get_available_actions()}

    def close(self, env):
        self.server.user_sessions.pop(env.session, None)
        env.close()


class SessionPool:
    """One shared simulator with isolated session IDs and serialized mutation."""
    def __init__(self, backend, size=32, idle_ttl_seconds=3600, clock=time.monotonic):
        if size < 1 or idle_ttl_seconds <= 0:
            raise ValueError("pool size and idle TTL must be positive")
        self.backend, self.size = backend, size
        self.idle_ttl_seconds, self.clock = idle_ttl_seconds, clock
        self.expired_sessions = 0
        self.sessions = {}
        self.released = {}
        self.stats = {"reset_replays": 0, "step_replays": 0, "operations": 0,
                      "queue_seconds": 0.0, "backend_seconds": 0.0,
                      "max_queue_seconds": 0.0, "max_backend_seconds": 0.0}
        self.lock = threading.RLock()

    def meta(self):
        with self.lock:
            return {"num_goals": self.backend.num_goals, "pool": self.size, "active": len(self.sessions),
                    "option_fix": self.backend.option_fix, "reconstructed": True, "service_revision": SERVICE_REVISION,
                    "transport_protocol": TRANSPORT_PROTOCOL, "transport_stats": dict(self.stats),
                    "idle_ttl_seconds": self.idle_ttl_seconds, "expired_sessions": self.expired_sessions,
                    "provenance": self.backend.provenance}

    def reset(self, goal_idx, request_id=None):
        if type(goal_idx) is not int or not 0 <= goal_idx < self.backend.num_goals:
            raise ServiceError(400, "goal_idx is outside the complete goal set")
        if request_id is not None and (not isinstance(request_id, str) or
                                       len(request_id) != 32 or
                                       any(c not in "0123456789abcdef" for c in request_id)):
            raise ServiceError(400, "request_id must be a lowercase UUID hex string")
        with self.lock:
            now = self.clock()
            self.released = {sid: t for sid, t in self.released.items()
                             if now - t <= self.idle_ttl_seconds}
            if request_id in self.released:
                raise ServiceError(409, "reset request belongs to a released episode")
            if request_id in self.sessions:
                session = self.sessions[request_id]
                if session["initial"]["goal_idx"] != goal_idx:
                    raise ServiceError(409, "reset request_id reused with a different goal")
                session["last_used"] = now
                self.stats["reset_replays"] += 1
                return session["initial"]
            expired = [sid for sid, session in self.sessions.items()
                       if now - session["last_used"] > self.idle_ttl_seconds]
            for sid in expired:
                self.release(sid)
                self.expired_sessions += 1
            if len(self.sessions) >= self.size:
                raise ServiceError(429, "session pool is full; release an episode and retry")
            sid = request_id or uuid.uuid4().hex
            env, result = self.backend.create(goal_idx, sid)
            initial = {**result, "sid": sid, "goal_idx": goal_idx}
            self.sessions[sid] = {"env": env, "done": False, "last_used": self.clock(),
                                  "initial": initial, "steps": {}, "poisoned": False}
            return initial

    def step(self, sid, action, sequence=None):
        if not isinstance(action, str):
            raise ServiceError(400, "action must be a string")
        with self.lock:
            session = self.sessions.get(sid) if isinstance(sid, str) else None
            if session is None:
                raise ServiceError(404, "unknown or released sid")
            if sequence is not None:
                if type(sequence) is not int or not 0 <= sequence < 128:
                    raise ServiceError(400, "sequence must be an integer in [0,128)")
                cached = session["steps"].get(sequence)
                if cached is not None:
                    if cached[0] != action:
                        raise ServiceError(409, "sequence reused with a different action")
                    session["last_used"] = self.clock()
                    self.stats["step_replays"] += 1
                    return cached[1]
                if sequence != len(session["steps"]):
                    raise ServiceError(409, "out-of-order action sequence")
            if session["poisoned"]:
                raise ServiceError(500, "previous backend error; episode cannot be retried safely")
            if session["done"]:
                raise ServiceError(409, "episode has ended; release it before starting another")
            try:
                result = self.backend.step(session["env"], action)
                if not math.isfinite(result["reward"]):
                    raise ServiceError(500, "environment returned nonfinite reward")
            except Exception:
                session["poisoned"] = True
                raise
            if sequence is not None:
                session["steps"][sequence] = (action, result)
            session["done"] = result["done"]
            session["last_used"] = self.clock()
            return result

    def release(self, sid):
        if not isinstance(sid, str):
            raise ServiceError(400, "sid must be a string")
        with self.lock:
            session = self.sessions.pop(sid, None)
            if session is not None:
                self.backend.close(session["env"])
                self.released[sid] = self.clock()
            return {"released": session is not None}

    def execute(self, path, data):
        """Measure queueing separately from serialized simulator execution."""
        started = self.clock()
        with self.lock:
            acquired = self.clock()
            try:
                if path == "/reset":
                    return self.reset(data.get("goal_idx"), data.get("request_id"))
                if path == "/step":
                    return self.step(data.get("sid"), data.get("action"), data.get("sequence"))
                if path == "/release":
                    return self.release(data.get("sid"))
                raise ServiceError(404, "unknown endpoint")
            finally:
                elapsed = self.clock() - acquired
                queued = acquired - started
                self.stats["operations"] += 1
                for key, value in (("queue_seconds", queued), ("backend_seconds", elapsed)):
                    self.stats[key] += value
                    self.stats["max_" + key] = max(self.stats["max_" + key], value)


class WebshopHTTPServer(ThreadingHTTPServer):
    # The stdlib default (5) drops bursts before the HTTP handler is reached.
    request_queue_size = 1024
    daemon_threads = True


def make_handler(pool):
    class Handler(BaseHTTPRequestHandler):
        def reply(self, status, data):
            payload = json.dumps(data, ensure_ascii=False, allow_nan=False).encode()
            try:
                self.send_response(status)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Content-Length", str(len(payload)))
                self.end_headers()
                self.wfile.write(payload)
            except (BrokenPipeError, ConnectionResetError):
                # Mutation and cached result are committed. A retry can recover
                # that result; writing a second response cannot repair a socket.
                self.log_error("client disconnected after status %s", status)

        def do_GET(self):
            if self.path in ("/meta", "/health"):
                self.reply(200, pool.meta())
            else:
                self.reply(404, {"error": "unknown endpoint"})

        def do_POST(self):
            try:
                length = int(self.headers.get("Content-Length", "0"))
                if not 0 < length <= 1024 * 1024:
                    raise ServiceError(400, "JSON body must be between 1 byte and 1 MiB")
                data = json.loads(self.rfile.read(length))
                if not isinstance(data, dict):
                    raise ServiceError(400, "JSON body must be an object")
                result = pool.execute(self.path, data)
                self.reply(200, result)
            except ServiceError as exc:
                self.reply(exc.status, {"error": str(exc)})
            except (ValueError, TypeError) as exc:
                self.reply(400, {"error": str(exc)})
            except Exception as exc:
                self.log_error("environment failure: %s", type(exc).__name__)
                self.reply(500, {"error": "environment failure; inspect the service log"})

        def log_message(self, fmt, *args):
            # Avoid logging instructions or action payloads.
            sys.stderr.write(f"[webshop-http] {datetime.now(timezone.utc).isoformat()} {self.address_string()} {fmt % args}\n")
    return Handler


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--upstream", type=Path, required=True)
    parser.add_argument("--port", type=int, default=8310)
    parser.add_argument("--pool-size", type=int, default=32)
    parser.add_argument("--idle-ttl-seconds", type=float, default=3600)
    parser.add_argument("--option-fix", choices=("on", "off"), default="on")
    parser.add_argument("--manifest", type=Path, required=True, help="New provenance JSON; must not already exist")
    args = parser.parse_args(argv)
    if args.manifest.exists():
        parser.error("manifest already exists; use a new path for this service launch")
    backend = OfficialBackend(args.upstream, option_fix=args.option_fix == "on")
    pool = SessionPool(backend, args.pool_size, args.idle_ttl_seconds)
    server = WebshopHTTPServer(("127.0.0.1", args.port), make_handler(pool))
    args.manifest.parent.mkdir(parents=True, exist_ok=True)
    with args.manifest.open("x", encoding="utf-8") as handle:
        json.dump({**pool.meta(), "host": "127.0.0.1", "port": args.port,
                   "created_at": datetime.now(timezone.utc).isoformat()}, handle, indent=2)
        handle.write("\n")
    print(json.dumps({"ready": True, "host": "127.0.0.1", "port": args.port, "reconstructed": True,
                      "service_revision": SERVICE_REVISION}), flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        for sid in list(pool.sessions):
            pool.release(sid)


if __name__ == "__main__":
    main()
